-- Gerado por scripts/gerar_seed.py a partir de data/cofz/ambientes.json e data/cofz/plantas.json — não editar à mão

begin;




update public.ambiente a set ativo = false from public.obra o where a.obra_id = o.id and o.slug = 'cofz' and a.ativo and a.codigo <> all (array['terreo-circulacao-1', 'terreo-circulacao-2', 'terreo-circulacao-3', 'terreo-comissao-de-obras', 'terreo-copa', 'terreo-cpd', 'terreo-dml', 'terreo-recepcao', 'terreo-sala-da', 'terreo-sala-da-chefia', 'terreo-sala-de-apoio', 'terreo-sala-de-controle', 'terreo-sala-de-reunioes', 'terreo-sala-imersiva', 'terreo-salao-de-acesso', 'terreo-wc-da-chefia', 'terreo-wc-feminino', 'terreo-wc-masculino', 'terreo-wc-pcd']::text[]);

update public.planta pl set ativa = false from public.obra o join public.pavimento p on p.obra_id = o.id and p.codigo = 'terreo' where o.slug = 'cofz' and pl.pavimento_id = p.id and pl.revisao <> 'R06' and pl.ativa;


commit;
